// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address callee, bytes memory data) public {
        vm.assume(callee != address(c));
        Reverter reverter = new Reverter();
        bool ok;
        try c.forward(address(reverter), data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
contract Reverter {
    fallback() external payable { revert(); }
}
